from threetears.evals import Eval

from address import label_lines

def print_label(case):
    """The label lines for the order's address."""
    return {"lines": label_lines(case["address"])}


def matches_courier(case, out):
    """The label is the one the courier's system prints."""
    return out["lines"] == case["courier_label"]

labels = Eval("data/order_addresses.jsonl", runner=print_label, grader=[matches_courier], k=1)
